const listContracts = `-- name: ListContracts :many
SELECT c.id, c.number, c.legal_basis, c.property_id, c.tenant_id, c.status, c.concluded_on, c.start_date, c.end_date, c.termination_date, c.termination_reason, c.termination_initiator, c.actual_end_date, c.registration_required, c.is_short_term, c.registration_done_on, c.registration_number, c.first_due_date, c.deposit_kop, c.utilities_mode, c.penalty_enabled, c.penalty_rate_pct, c.penalty_grace_days, c.penalty_cap_pct, c.penalty_on_utilities, c.indexation_enabled, c.indexation_pct, c.indexation_period_months, c.next_indexation_on, c.special_terms, c.notes, c.activated_at, c.activated_by, c.closed_at, c.created_by, c.created_at, c.updated_at, p.code AS property_code, t.kind AS tenant_kind, t.last_name, t.first_name, t.middle_name, t.org_name,
       (SELECT ct.rent_kop FROM contract_terms ct WHERE ct.contract_id = c.id AND ct.effective_from <= GREATEST(c.start_date, $1::date)
        ORDER BY ct.effective_from DESC LIMIT 1)::bigint AS rent_kop
FROM contracts c
JOIN properties p ON p.id = c.property_id
JOIN tenants t ON t.id = c.tenant_id
WHERE (cardinality($2::text[]) = 0 OR c.status = ANY($2::text[]))
  AND ($3::uuid IS NULL OR c.property_id = $3)
  AND ($4::uuid IS NULL OR c.tenant_id = $4)
  AND ($5::date IS NULL OR (c.status IN ('active', 'extended') AND c.end_date <= $5))
  AND ($6::text IS NULL OR c.number ILIKE '%' || $6 || '%' OR p.code ILIKE '%' || $6 || '%'
       OR concat_ws(' ', t.last_name, t.first_name, t.middle_name) ILIKE '%' || $6 || '%'
       OR t.org_name ILIKE '%' || $6 || '%')
ORDER BY
  CASE WHEN $7::text = 'startDate' THEN c.start_date END ASC,
  CASE WHEN $7::text = '-startDate' THEN c.start_date END DESC,
  CASE WHEN $7::text = 'endDate' THEN c.end_date END ASC,
  CASE WHEN $7::text = '-endDate' THEN c.end_date END DESC,
  CASE WHEN $7::text = 'number' THEN c.number END ASC,
  c.number DESC
LIMIT $9 OFFSET $8
`

