const statusHistoryFrom = `-- name: StatusHistoryFrom :many

SELECT id, property_id, status, valid_from, valid_to, contract_id, reason, created_by, created_at FROM property_status_history
WHERE property_id = $1 AND (valid_to IS NULL OR valid_to >= $2::date)
ORDER BY valid_from
`

type StatusHistoryFromParams struct {
	PropertyID uuid.UUID
	FromDate   date.Date
}

// Статусы объекта по договору (05 разд. 4.4, 4.7, 4.8)
// Записи истории объекта, пересекающие дату и позже (для постановки «Сдан» с даты начала).
func (q *Queries) StatusHistoryFrom(ctx context.Context, arg StatusHistoryFromParams) ([]PropertyStatusHistory, error) {
	rows, err := q.db.Query(ctx, statusHistoryFrom, arg.PropertyID, arg.FromDate)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []PropertyStatusHistory{}
	for rows.Next() {
		var i PropertyStatusHistory
		if err := rows.Scan(
			&i.ID,
			&i.PropertyID,
			&i.Status,
			&i.ValidFrom,
			&i.ValidTo,
			&i.ContractID,
			&i.Reason,
			&i.CreatedBy,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

